export interface WorkflowAPI {
  /**
   * RestartWorkflowExecution restarts a previous workflow
   * If the workflow is currently running it will terminate and restart
   */
  RestartWorkflowExecution(request: RestartWorkflowExecutionRequest): Promise<RestartWorkflowExecutionResponse>;
  /**
   * StartWorkflowExecution starts a new long running workflow instance.  It will create the instance with
   * 'WorkflowExecutionStarted' event in history and also schedule the first DecisionTask for the worker to make the
   * first decision for this instance.  It will return 'WorkflowExecutionAlreadyStartedError', if an instance already
   * exists with same workflowId.
   */
  StartWorkflowExecution(request: StartWorkflowExecutionRequest): Promise<StartWorkflowExecutionResponse>;
  /**
   * StartWorkflowExecutionAsync starts a new long running workflow instance asynchronously. It will push a StartWorkflowExecutionRequest to a queue
   * and immediately return a response. The request will be processed by a separate consumer eventually.
   */
  StartWorkflowExecutionAsync(
    request: StartWorkflowExecutionAsyncRequest,
  ): Promise<StartWorkflowExecutionAsyncResponse>;
  /**
   * SignalWorkflowExecution is used to send a signal event to running workflow execution.  This results in
   * WorkflowExecutionSignaled event recorded in the history and a decision task being created for the execution.
   */
  SignalWorkflowExecution(request: SignalWorkflowExecutionRequest): Promise<SignalWorkflowExecutionResponse>;
  /**
   * SignalWithStartWorkflowExecution is used to ensure sending signal to a workflow.  If the workflow is running,
   * this results in WorkflowExecutionSignaled event being recorded in the history and a decision task being created for
   * the execution.  If the workflow is not running or not found, this results in WorkflowExecutionStarted and
   * WorkflowExecutionSignaled events being recorded in history, and a decision task being created for the execution.
   */
  SignalWithStartWorkflowExecution(
    request: SignalWithStartWorkflowExecutionRequest,
  ): Promise<SignalWithStartWorkflowExecutionResponse>;
  /**
   * SignalWithStartWorkflowExecutionAsync is used to ensure sending signal to a workflow asynchronously.  It will push a SignalWithStartWorkflowExecutionRequest to a queue
   * and immediately return a response. The request will be processed by a separate consumer eventually.
   */
  SignalWithStartWorkflowExecutionAsync(
    request: SignalWithStartWorkflowExecutionAsyncRequest,
  ): Promise<SignalWithStartWorkflowExecutionAsyncResponse>;
  /**
   * ResetWorkflowExecution reset an existing workflow execution to DecisionTaskCompleted event(exclusive).
   * And it will immediately terminating the current execution instance.
   */
  ResetWorkflowExecution(request: ResetWorkflowExecutionRequest): Promise<ResetWorkflowExecutionResponse>;
  /**
   * RequestCancelWorkflowExecution requests cancellation of a workflow instance.
   * It allows workflow to properly clean up and gracefully close.
   */
  RequestCancelWorkflowExecution(
    request: RequestCancelWorkflowExecutionRequest,
  ): Promise<RequestCancelWorkflowExecutionResponse>;
  /**
   * TerminateWorkflowExecution terminates an existing workflow execution by recording WorkflowExecutionTerminated event
   * in the history and immediately terminating the execution instance.
   */
  TerminateWorkflowExecution(request: TerminateWorkflowExecutionRequest): Promise<TerminateWorkflowExecutionResponse>;
  /** DescribeWorkflowExecution returns information about the specified workflow execution. */
  DescribeWorkflowExecution(request: DescribeWorkflowExecutionRequest): Promise<DescribeWorkflowExecutionResponse>;
  /** QueryWorkflow returns query result for a specified workflow execution. */
  QueryWorkflow(request: QueryWorkflowRequest): Promise<QueryWorkflowResponse>;
  /**
   * DescribeTaskList returns information about the target task list, including
   * the workers that polled it in the last few minutes.
   */
  DescribeTaskList(request: DescribeTaskListRequest): Promise<DescribeTaskListResponse>;
  /** GetTaskListsByDomain returns all task lists for a given domain */
  GetTaskListsByDomain(request: GetTaskListsByDomainRequest): Promise<GetTaskListsByDomainResponse>;
  /** ListTaskListPartitions returns information about task list partitions. */
  ListTaskListPartitions(request: ListTaskListPartitionsRequest): Promise<ListTaskListPartitionsResponse>;
  /** GetClusterInfo returns information about cadence cluster. */
  GetClusterInfo(request: GetClusterInfoRequest): Promise<GetClusterInfoResponse>;
  /**
   * Returns the history of specified workflow execution.  It fails with 'EntityNotExistError' if specified workflow
   * execution in unknown to the service.
   */
  GetWorkflowExecutionHistory(
    request: GetWorkflowExecutionHistoryRequest,
  ): Promise<GetWorkflowExecutionHistoryResponse>;
  /** RefreshWorkflowTasks refreshes all tasks of a workflow. */
  RefreshWorkflowTasks(request: RefreshWorkflowTasksRequest): Promise<RefreshWorkflowTasksResponse>;
  /** Diagnoses a workflow execution and provides a report as response */
  DiagnoseWorkflowExecution(request: DiagnoseWorkflowExecutionRequest): Promise<DiagnoseWorkflowExecutionResponse>;
}

